"use server";

import { redirect } from "next/navigation";
import { revalidatePath } from "next/cache";
import bcrypt from "bcryptjs";
import { z } from "zod";
import { db } from "./db";
import { createSession, destroySession, requireUser, requireAdmin, currentUser } from "./auth";
import { capacityCheck } from "./capacity";

async function audit(userId: string | null, action: string, detail?: string) {
  await db.auditLog.create({ data: { userId, action, detail } });
}

// ---------- Auth ----------

const credsSchema = z.object({
  email: z.string().email().max(200),
  password: z.string().min(8).max(200),
});

export async function register(prev: any, formData: FormData): Promise<{ error?: string }> {
  const parsed = credsSchema.extend({ name: z.string().min(1).max(100) }).safeParse({
    email: formData.get("email"),
    password: formData.get("password"),
    name: formData.get("name"),
  });
  if (!parsed.success) return { error: "Enter a valid email, name, and password (min 8 chars)." };
  const { email, password, name } = parsed.data;

  const existing = await db.user.findUnique({ where: { email } });
  if (existing) return { error: "An account with that email already exists." };

  const user = await db.user.create({
