import { createInvoice, type LineItem } from "@/lib/invoices";

async function audit(userId: string | null, action: string, detail?: string) {
  await db.auditLog.create({ data: { userId, action, detail } });
}

/**
 * Admin: generate an OPEN invoice for a server's current plan (one billing
 * period). Does not charge the wallet — it records what is owed; the wallet
 * ledger and invoices are complementary records.
 */
export async function generateInvoiceForServer(serverId: string) {
  const admin = await requireAdmin();
  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { plan: true, user: { select: { id: true, email: true } } },
  });
  if (!server) throw new Error("Server not found");
  if (server.isFree) throw new Error("Free servers are not billed");

  const now = new Date();
  const periodEnd = new Date(now.getTime() + 30 * 86400_000);
  const line: LineItem = {
    description: `${server.plan.name} — ${server.hostname}`,
    qty: 1,
    unitCents: server.plan.priceCents,
    amountCents: server.plan.priceCents,
  };

  const invoice = await createInvoice({
    userId: server.userId,
    description: `${server.plan.name} plan · ${server.hostname}`,
    lineItems: [line],
    status: "OPEN",
    period: { start: now, end: periodEnd },
  });

  await audit(
    admin.id,
    "invoice.generate",
    `#${invoice.number} for ${server.hostname} (${server.user.email})`
  );
  revalidatePath("/admin/invoices");
  revalidatePath("/dashboard/invoices");
  return { id: invoice.id, number: invoice.number };
}

/** Admin: void an open/unpaid invoice. */
export async function voidInvoice(id: string) {
  const admin = await requireAdmin();
  const invoice = await db.invoice.findUnique({ where: { id } });
  if (!invoice) throw new Error("Invoice not found");
  if (invoice.status === "PAID") throw new Error("Paid invoices cannot be voided — refund instead");
  if (invoice.status === "VOID") return { ok: true };

  await db.invoice.update({ where: { id }, data: { status: "VOID", paidAt: null } });
  await audit(admin.id, "invoice.void", `#${invoice.number}`);
  revalidatePath("/admin/invoices");
  revalidatePath(`/admin/invoices/${id}`);
  revalidatePath("/dashboard/invoices");
  return { ok: true };
}

/** Admin: mark an invoice paid. */
export async function markInvoicePaid(id: string) {
  const admin = await requireAdmin();
  const invoice = await db.invoice.findUnique({ where: { id } });
  if (!invoice) throw new Error("Invoice not found");
  if (invoice.status === "VOID") throw new Error("Void invoices cannot be marked paid");
  if (invoice.status === "PAID") return { ok: true };

  await db.invoice.update({ where: { id }, data: { status: "PAID", paidAt: new Date() } });
  await audit(admin.id, "invoice.mark_paid", `#${invoice.number}`);
  revalidatePath("/admin/invoices");
  revalidatePath(`/admin/invoices/${id}`);
  revalidatePath("/dashboard/invoices");
  return { ok: true };
}

/**
 * Admin: generate OPEN invoices for every paid, active server that has no
 * invoice yet. Best-effort backfill — safe to run repeatedly.
 */
export async function regenerateMissingInvoices() {
  const admin = await requireAdmin();
  const servers = await db.server.findMany({
    where: { isFree: false, status: { not: "DELETING" } },
    include: { plan: true },
  });

  let created = 0;
  for (const server of servers) {
    const existing = await db.invoice.count({
      where: {
        userId: server.userId,
        description: { contains: server.hostname },
        status: { not: "VOID" },
      },
    });
    if (existing > 0) continue;
    const now = new Date();
    await createInvoice({
      userId: server.userId,
      description: `${server.plan.name} plan · ${server.hostname}`,
      lineItems: [
        {
          description: `${server.plan.name} — ${server.hostname}`,
          qty: 1,
          unitCents: server.plan.priceCents,
          amountCents: server.plan.priceCents,
        },
      ],
      status: "OPEN",
      period: { start: now, end: new Date(now.getTime() + 30 * 86400_000) },
    });
    created++;
  }

  await audit(admin.id, "invoice.regenerate_missing", `${created} created`);
  revalidatePath("/admin/invoices");
  revalidatePath("/dashboard/invoices");
  return { created };
}

import { NextRequest, NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { renderInvoiceHTML } from "@/lib/invoices";

/**
 * Returns the branded, print-ready invoice as standalone HTML.
 *
 * NOTE: There is no PDF library installed and we cannot add dependencies, so
 * this is the pragmatic approach — the page ships with a print-optimised
 * stylesheet and a "Print / Save as PDF" button; the browser's Print → Save
 * as PDF produces the downloadable document.
 */
export async function GET(_req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const invoice = await db.invoice.findUnique({
    where: { id },
    include: { user: { select: { name: true, email: true } } },
  });
  if (!invoice) return NextResponse.json({ error: "not found" }, { status: 404 });

  const isOwner = invoice.userId === user.id;
  const isAdmin = user.role === "ADMIN";
  if (!isOwner && !isAdmin) {
    return NextResponse.json({ error: "forbidden" }, { status: 403 });
  }

  const html = renderInvoiceHTML(invoice, invoice.user);
  return new NextResponse(html, {
    status: 200,
    headers: {
      "Content-Type": "text/html; charset=utf-8",
      "Cache-Control": "private, no-store",
    },
  });
}

import type { InvoiceStatus } from "@prisma/client";
import { Badge } from "@/components/ui/primitives";

const TONE: Record<InvoiceStatus, "brand" | "green" | "red" | "amber" | "slate"> = {
  OPEN: "amber",
  PAID: "green",
  VOID: "slate",
  REFUNDED: "brand",
};

const LABEL: Record<InvoiceStatus, string> = {
  OPEN: "Open",
  PAID: "Paid",
  VOID: "Void",
  REFUNDED: "Refunded",
};

export function InvoiceStatusBadge({ status }: { status: InvoiceStatus }) {
  return <Badge tone={TONE[status] ?? "slate"}>{LABEL[status] ?? status}</Badge>;
}

/** Anchor (not Link) — the target is a raw HTML document served by the API route. */
export function DownloadInvoiceButton({
  id,
  className = "btn-secondary py-1.5",
  label = "Download / Print",
}: {
  id: string;
  className?: string;
  label?: string;
}) {
  return (
    <a href={`/api/invoices/${id}`} target="_blank" rel="noopener noreferrer" className={className}>
      {label}
    </a>
  );
}

"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import {
  markInvoicePaid,
  voidInvoice,
  generateInvoiceForServer,
  regenerateMissingInvoices,
} from "@/lib/actions-billing";

export function InvoiceAdminActions({ id, status }: { id: string; status: string }) {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [err, setErr] = useState<string | null>(null);

  const run = (fn: () => Promise<unknown>) => {
    setErr(null);
    start(async () => {
      try {
        await fn();
        router.refresh();
      } catch (e) {
        setErr(e instanceof Error ? e.message : "Action failed");
      }
    });
  };

  const terminal = status === "VOID";
  return (
    <div className="flex flex-wrap items-center gap-2">
      <button
        className="btn-secondary py-1.5"
        disabled={pending || status === "PAID" || terminal}
        onClick={() => run(() => markInvoicePaid(id))}
      >
        Mark paid
      </button>
      <button
        className="btn-danger py-1.5"
        disabled={pending || status === "PAID" || terminal}
        onClick={() => {
          if (window.confirm("Void this invoice? It will no longer be collectible.")) {
            run(() => voidInvoice(id));
          }
        }}
      >
        Void
      </button>
      {err && <span className="text-xs text-red-400">{err}</span>}
    </div>
  );
}

export function GenerateInvoiceButton({
  serverId,
  label = "Generate invoice",
}: {
  serverId: string;
  label?: string;
}) {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [err, setErr] = useState<string | null>(null);
  return (
    <div className="flex items-center gap-2">
      <button
        className="btn-secondary py-1.5"
        disabled={pending}
        onClick={() => {
          setErr(null);
          start(async () => {
            try {
              await generateInvoiceForServer(serverId);
              router.refresh();
            } catch (e) {
              setErr(e instanceof Error ? e.message : "Failed");
            }
          });
        }}
      >
        {pending ? "Generating…" : label}
      </button>
      {err && <span className="text-xs text-red-400">{err}</span>}
    </div>
  );
}

export function RegenerateMissingButton() {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<string | null>(null);
  return (
    <div className="flex items-center gap-2">
      <button
        className="btn-secondary py-1.5"
        disabled={pending}
        onClick={() => {
          setMsg(null);
          start(async () => {
            try {
              const r = await regenerateMissingInvoices();
              setMsg(`${r.created} created`);
              router.refresh();
            } catch (e) {
              setMsg(e instanceof Error ? e.message : "Failed");
            }
          });
        }}
      >
        {pending ? "Backfilling…" : "Backfill missing"}
      </button>
      {msg && <span className="text-xs text-slate-400">{msg}</span>}
    </div>
  );
}

import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
