import Link from "next/link";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { PageHeader, fmtMoney } from "@/components/ui/primitives";
import { InvoiceStatusBadge, DownloadInvoiceButton } from "@/components/customer/InvoiceViews";
import { invoiceTotals } from "@/lib/invoices";

export const dynamic = "force-dynamic";

function fmtDate(d: Date | null | undefined): string {
  if (!d) return "—";
  return new Date(d).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });
}

export default async function CustomerInvoiceDetail({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const user = await requireUser();
  const { id } = await params;

  const invoice = await db.invoice.findUnique({ where: { id } });
  if (!invoice || invoice.userId !== user.id) notFound();

  const { items, subtotalCents, taxCents, totalCents } = invoiceTotals(invoice);
  const number = String(invoice.number).padStart(5, "0");
  const period =
    invoice.periodStart || invoice.periodEnd
      ? `${fmtDate(invoice.periodStart)} – ${fmtDate(invoice.periodEnd)}`
      : null;

  return (
    <div className="space-y-6">
      <PageHeader title={`Invoice #${number}`} sub={invoice.description}>
        <Link href="/dashboard/invoices" className="btn-ghost py-1.5">
          All invoices
        </Link>
        <DownloadInvoiceButton id={invoice.id} />
      </PageHeader>

      <div className="card space-y-6">
        <div className="flex flex-wrap items-start justify-between gap-4">
          <div className="grid grid-cols-2 gap-x-10 gap-y-3 text-sm">
            <div>
              <p className="section-label mb-1">Billed to</p>
              <p className="font-medium">{user.name}</p>
              <p className="text-slate-400">{user.email}</p>
            </div>
            <div>
              <p className="section-label mb-1">Issued</p>
              <p className="font-medium">{fmtDate(invoice.createdAt)}</p>
              {invoice.paidAt && <p className="text-slate-400">Paid {fmtDate(invoice.paidAt)}</p>}
            </div>
            {period && (
              <div>
                <p className="section-label mb-1">Service period</p>
                <p className="font-medium">{period}</p>
              </div>
            )}
          </div>
          <InvoiceStatusBadge status={invoice.status} />
        </div>

        <div className="overflow-x-auto">
          <table className="table-shell min-w-[520px]">
            <thead>
              <tr>
                <th>Description</th>
                <th className="text-right">Qty</th>
                <th className="text-right">Unit</th>
                <th className="text-right">Amount</th>
              </tr>
            </thead>
            <tbody>
              {items.length === 0 ? (
                <tr>
                  <td colSpan={4}>{invoice.description}</td>
                </tr>
              ) : (
                items.map((li, i) => (
                  <tr key={i}>
                    <td>{li.description}</td>
                    <td className="text-right font-mono">{li.qty}</td>
                    <td className="text-right font-mono">{fmtMoney(li.unitCents)}</td>
                    <td className="text-right font-mono">{fmtMoney(li.amountCents)}</td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        <div className="flex justify-end">
          <div className="w-full max-w-xs space-y-2 text-sm">
            <div className="flex justify-between text-slate-400">
              <span>Subtotal</span>
              <span className="font-mono text-slate-200">{fmtMoney(subtotalCents)}</span>
            </div>
            <div className="flex justify-between text-slate-400">
              <span>Tax</span>
              <span className="font-mono text-slate-200">{fmtMoney(taxCents)}</span>
            </div>
            <div className="flex justify-between border-t border-white/10 pt-2 text-base font-semibold">
              <span>Total</span>
              <span className="font-mono">{fmtMoney(totalCents)}</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import Link from "next/link";
import { requireAdmin } from "@/lib/auth";
import { db } from "@/lib/db";
import { PageHeader, StatCard, fmtMoney, timeAgo } from "@/components/ui/primitives";
import { InvoiceStatusBadge } from "@/components/customer/InvoiceViews";
import { RegenerateMissingButton } from "@/components/admin/InvoiceAdmin";
import type { InvoiceStatus } from "@prisma/client";

export const dynamic = "force-dynamic";

const STATUSES: InvoiceStatus[] = ["OPEN", "PAID", "VOID", "REFUNDED"];

export default async function AdminInvoices({
  searchParams,
}: {
  searchParams: Promise<{ status?: string }>;
}) {
  await requireAdmin();
  const sp = await searchParams;
  const status = STATUSES.includes(sp.status as InvoiceStatus)
    ? (sp.status as InvoiceStatus)
    : undefined;

  const [invoices, issued, paid, outstanding] = await Promise.all([
    db.invoice.findMany({
      where: status ? { status } : {},
      include: { user: { select: { id: true, email: true, name: true } } },
      orderBy: { createdAt: "desc" },
      take: 200,
    }),
    db.invoice.aggregate({ where: { status: { not: "VOID" } }, _sum: { amountCents: true } }),
    db.invoice.aggregate({ where: { status: "PAID" }, _sum: { amountCents: true } }),
    db.invoice.aggregate({ where: { status: "OPEN" }, _sum: { amountCents: true } }),
  ]);

  const chip = (href: string, label: string, active: boolean) => (
    <Link
      href={href}
      className={`rounded-full border px-3 py-1 text-xs font-medium transition-colors ${
        active
          ? "border-brand-500/40 bg-brand-500/10 text-brand-300"
          : "border-white/10 bg-white/[0.04] text-slate-400 hover:text-slate-200"
      }`}
    >
      {label}
    </Link>
  );

  return (
    <div className="space-y-6">
      <PageHeader title="Invoices" sub="All billing documents issued across the platform.">
        <Link href="/admin/billing" className="btn-ghost py-1.5">
          Billing
        </Link>
        <RegenerateMissingButton />
      </PageHeader>

      <div className="grid grid-cols-2 gap-4 xl:grid-cols-4">
        <StatCard label="Issued · total" value={fmtMoney(issued._sum.amountCents ?? 0)} delta="excl. void" />
        <StatCard label="Paid" value={fmtMoney(paid._sum.amountCents ?? 0)} />
        <StatCard label="Outstanding" value={fmtMoney(outstanding._sum.amountCents ?? 0)} delta="open" deltaGood={false} />
        <StatCard label="Count" value={String(invoices.length)} delta={status ? `filtered: ${status.toLowerCase()}` : "all statuses"} />
      </div>

      <div className="card p-0">
        <div className="flex flex-wrap items-center justify-between gap-3 px-5 pt-5">
          <h2 className="font-semibold">Invoices</h2>
          <div className="flex items-center gap-2">
            {chip("/admin/invoices", "All", !status)}
            {STATUSES.map((s) =>
              chip(`/admin/invoices?status=${s}`, s.charAt(0) + s.slice(1).toLowerCase(), status === s)
            )}
          </div>
        </div>
        {invoices.length === 0 ? (
          <p className="px-5 py-10 text-center text-sm text-slate-500">No invoices found.</p>
        ) : (
          <div className="overflow-x-auto pt-3">
            <table className="table-shell min-w-[720px]">
              <thead>
                <tr>
                  <th>Number</th>
                  <th>Client</th>
                  <th>Description</th>
                  <th>Status</th>
                  <th className="text-right">Amount</th>
                  <th className="text-right">Issued</th>
                </tr>
              </thead>
              <tbody>
                {invoices.map((inv) => (
                  <tr key={inv.id}>
                    <td className="font-mono text-xs text-slate-300">
                      <Link href={`/admin/invoices/${inv.id}`} className="hover:text-brand-300">
                        #{String(inv.number).padStart(5, "0")}
                      </Link>
                    </td>
                    <td>
                      <Link href={`/admin/users/${inv.user.id}`} className="hover:text-brand-300">
                        {inv.user.email}
                      </Link>
                    </td>
                    <td className="max-w-xs truncate">
                      <Link href={`/admin/invoices/${inv.id}`} className="hover:text-brand-300">
                        {inv.description}
                      </Link>
                    </td>
                    <td>
                      <InvoiceStatusBadge status={inv.status} />
                    </td>
                    <td className="text-right font-mono">{fmtMoney(inv.amountCents)}</td>
                    <td className="text-right text-xs text-slate-400" title={inv.createdAt.toISOString()}>
                      {timeAgo(inv.createdAt)}
