              </tbody>
            </table>
          </div>
        )}
        <p className="px-5 py-4 text-xs text-slate-500">Showing the latest 200 matching invoices.</p>
      </div>
    </div>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { requireAdmin } from "@/lib/auth";
import { db } from "@/lib/db";
import { PageHeader, fmtMoney } from "@/components/ui/primitives";
import { InvoiceStatusBadge, DownloadInvoiceButton } from "@/components/customer/InvoiceViews";
import { InvoiceAdminActions } from "@/components/admin/InvoiceAdmin";
import { invoiceTotals } from "@/lib/invoices";

export const dynamic = "force-dynamic";

function fmtDate(d: Date | null | undefined): string {
  if (!d) return "—";
  return new Date(d).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });
}

export default async function AdminInvoiceDetail({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  await requireAdmin();
  const { id } = await params;

  const invoice = await db.invoice.findUnique({
    where: { id },
    include: { user: { select: { id: true, name: true, email: true } } },
  });
  if (!invoice) notFound();

  const { items, subtotalCents, taxCents, totalCents } = invoiceTotals(invoice);
  const number = String(invoice.number).padStart(5, "0");
  const period =
    invoice.periodStart || invoice.periodEnd
      ? `${fmtDate(invoice.periodStart)} – ${fmtDate(invoice.periodEnd)}`
      : null;

  return (
    <div className="space-y-6">
      <PageHeader title={`Invoice #${number}`} sub={invoice.description}>
        <Link href="/admin/invoices" className="btn-ghost py-1.5">
          All invoices
        </Link>
        <DownloadInvoiceButton id={invoice.id} />
      </PageHeader>

      <div className="card flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <InvoiceStatusBadge status={invoice.status} />
          <span className="text-sm text-slate-400">Manage this invoice</span>
        </div>
        <InvoiceAdminActions id={invoice.id} status={invoice.status} />
      </div>

      <div className="card space-y-6">
        <div className="grid grid-cols-2 gap-x-10 gap-y-3 text-sm sm:grid-cols-3">
          <div>
            <p className="section-label mb-1">Billed to</p>
            <Link href={`/admin/users/${invoice.user.id}`} className="font-medium hover:text-brand-300">
              {invoice.user.name}
            </Link>
            <p className="text-slate-400">{invoice.user.email}</p>
          </div>
          <div>
            <p className="section-label mb-1">Issued</p>
            <p className="font-medium">{fmtDate(invoice.createdAt)}</p>
            {invoice.paidAt && <p className="text-slate-400">Paid {fmtDate(invoice.paidAt)}</p>}
          </div>
          {period && (
            <div>
              <p className="section-label mb-1">Service period</p>
              <p className="font-medium">{period}</p>
            </div>
          )}
        </div>

        <div className="overflow-x-auto">
          <table className="table-shell min-w-[520px]">
            <thead>
              <tr>
                <th>Description</th>
                <th className="text-right">Qty</th>
                <th className="text-right">Unit</th>
                <th className="text-right">Amount</th>
              </tr>
            </thead>
            <tbody>
              {items.length === 0 ? (
                <tr>
                  <td colSpan={4}>{invoice.description}</td>
                </tr>
              ) : (
                items.map((li, i) => (
                  <tr key={i}>
                    <td>{li.description}</td>
                    <td className="text-right font-mono">{li.qty}</td>
                    <td className="text-right font-mono">{fmtMoney(li.unitCents)}</td>
                    <td className="text-right font-mono">{fmtMoney(li.amountCents)}</td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        <div className="flex justify-end">
          <div className="w-full max-w-xs space-y-2 text-sm">
            <div className="flex justify-between text-slate-400">
              <span>Subtotal</span>
              <span className="font-mono text-slate-200">{fmtMoney(subtotalCents)}</span>
            </div>
            <div className="flex justify-between text-slate-400">
              <span>Tax</span>
              <span className="font-mono text-slate-200">{fmtMoney(taxCents)}</span>
            </div>
            <div className="flex justify-between border-t border-white/10 pt-2 text-base font-semibold">
              <span>Total</span>
              <span className="font-mono">{fmtMoney(totalCents)}</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

